body.script:
window.addEventListener('load', () => {
    // お問い合わせボタンをクリックしたらモーダルを開く
    document.querySelector('[data-micromodal-trigger="inquiry-modal"]').addEventListener('click', function () {
        App.Modal.show("inquiry-modal");
    });
    // モーダルを閉じるボタンを押したときにボタンからフォーカスを外す
    document.querySelectorAll('[data-micromodal-close]').forEach(element => {
        element.addEventListener('click', function () {
            document.querySelector('[data-micromodal-trigger="inquiry-modal"]').addEventListener('focus', function() {
                // フォーカス時の処理を記述
                document.querySelector('[data-micromodal-trigger="inquiry-modal"]').blur()
            });
        });
    });
    document.querySelector('#app-header-primary-nav-search').addEventListener('click', function () {
        document.querySelector('#app-header-primary-nav-search').blur();
    });
});
